// =============================================================
// components/Section/Section.jsx
// Wraps a page section with consistent padding, background
// color, optional title/subtitle, and a container.
// Props:
//   id       — string (for anchor links)
//   variant  — 'white' | 'light' | 'navy' | 'dark'
//   title    — string
//   subtitle — string
//   children — node
// =============================================================

import styles from './Section.module.css';

export default function Section({
  id,
  variant = 'white',
  title,
  subtitle,
  children,
  className = '',
}) {
  const isNavy = variant === 'navy' || variant === 'dark';

  return (
    <section
      id={id}
      className={[styles.section, styles[variant], className].join(' ')}
    >
      <div className="container">
        {(title || subtitle) && (
          <div className={styles.header}>
            {title && (
              <h2 className={[styles.title, isNavy ? styles.titleWhite : ''].join(' ')}>
                {title}
              </h2>
            )}
            {subtitle && (
              <p className={[styles.subtitle, isNavy ? styles.subtitleWhite : ''].join(' ')}>
                {subtitle}
              </p>
            )}
          </div>
        )}
        {children}
      </div>
    </section>
  );
}
